/usr/bin/zsh -lc "cat > contract.json <<'EOF'
{
  \"status\": \"frozen\",
  \"interface\": {
    \"top\": \"TopModule\",
    \"inputs\": {\"d\": 1, \"done_counting\": 1, \"ack\": 1, \"state\": 10},
    \"outputs\": {\"B3_next\": 1, \"S_next\": 1, \"S1_next\": 1, \"Count_next\": 1, \"Wait_next\": 1, \"done\": 1, \"counting\": 1, \"shift_ena\": 1}
  },
  \"semantics\": {
    \"evidence\": \"Original problem explicitly requests only state transition and output combinational logic using supplied one-hot state.\",
    \"state_bits\": {\"S\": 0, \"S1\": 1, \"S11\": 2, \"S110\": 3, \"B0\": 4, \"B1\": 5, \"B2\": 6, \"B3\": 7, \"Count\": 8, \"Wait\": 9},
    \"next_state_sources\": {\"B3_next\": \"B2\", \"S_next\": \"(S or S1 or S110) and not d, or Wait and ack\", \"S1_next\": \"S and d\", \"Count_next\": \"B3 or Count and not done_counting\", \"Wait_next\": \"Count and done_counting, or Wait and not ack\"},
    \"moore_outputs\": {\"done\": \"Wait\", \"counting\": \"Count\", \"shift_ena\": \"B0 or B1 or B2 or B3\"},
    \"latency\": \"Combinational propagation only; no clock or storage.\",
    \"reset_initialization\": \"Original reset-to-S describes external state storage. No reset or initialization is implemented in this combinational DUT; test reset condition by supplying state=1.\"
  },
  \"numeric\": {\"state\": \"Unsigned 10-bit one-hot vector, S at least significant bit\", \"signals\": \"Single-bit Boolean logic; no arithmetic or rounding\"},
  \"verification\": {
    \"oracle\": \"Independent transition-table destination per active original state, then collect requested destinations and Moore outputs\",
    \"coverage\": \"All 10 legal states with all 8 binary input combinations; supplemental all 1024 binary vectors with all 8 combinations to check OR equation extension\",
    \"sampling\": \"Drive inputs then wait one time unit for combinational settling\",
    \"safety\": \"Fatal on any mismatch, bounded timeout, PASS only after all checks\",
    \"primary_command\": \"python3 dev_check.py --label initial\"
  },
  \"specification_ambiguities\": [
    {\"issue\": \"Illegal zero-hot/multi-hot and X/Z state behavior is not explicitly specified\", \"resolution\": \"Use direct one-hot bitwise equations as requested, with OR superposition for binary multi-hot vectors; no recovery FSM or new state storage. Supplemental binary illegal-state tests validate this equation extension, not additional original requirements.\"}
  ]
}
EOF
python3 validate_contract.py"

